/** Basic fallback for WordPress posts and pages. */
?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="<?php echo esc_url(get_template_directory_uri() . '/styles.css?ver=' . filemtime(get_template_directory() . '/styles.css')); ?>"><?php wp_head(); ?></head><body <?php body_class(); ?>><main class="container section"><p><a href="<?php echo esc_url(home_url('/')); ?>"><span class="arrow-icon arrow-left" aria-hidden="true"></span> The Arrow Church</a></p><?php if (have_posts()) : while (have_posts()) : the_post(); ?><article><h1><?php the_title(); ?></h1><?php the_content(); ?></article><?php endwhile; endif; ?></main><?php wp_footer(); ?></body></html>
